interface Sale {
  round: number;
  price: number;
  nft_id: string;
  collection_id: number;
  collection_name: string;
  name: string;
  seller: string;
  buyer: string;
}

interface TokenBalance {
  contractId: number;
  tokenId: string;
  balance: string;
  decimals: number;
  symbol: string;
}

interface PointsResult {
  testnetPoints: number;
  mainnetPoints: number;
  pxdPoints: number;
  totalPoints: number;
  estimatedAirdrop: number;
  isEligible: boolean;
  uniqueTransactions: number;
  pxdBalance: number;
}

export const useAccountPoints = (address: string) => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [tokenBalances, setTokenBalances] = useState<TokenBalance[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [points, setPoints] = useState<PointsResult | null>(null);

  const TOTAL_AIRDROP = 10_000_000; // 10M tokens
  const TOTAL_POINTS =
    Object.values(testnetPoints).reduce((sum, points) => sum + points, 0) +
    100_000 * 3;

  useEffect(() => {
    const fetchData = async () => {
      if (!address) return;

      setIsLoading(true);
      setError(null);

      try {
        const [salesResponse, balancesResponse] = await Promise.all([
          fetch("https://mainnet-idx.nautilus.sh/nft-indexer/v1/mp/sales"),
          fetch(
            `https://mainnet-idx.nautilus.sh/nft-indexer/v1/arc200/balances?accountId=${address}`
          ),
        ]);

        if (!salesResponse.ok || !balancesResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const salesData = await salesResponse.json();
        const balancesData = await balancesResponse.json();

        setSales(salesData.sales || []);
        setTokenBalances(balancesData.balances || []);

        // Calculate points
        const cleanAddress = address.trim();
        const addressSales = salesData.sales.filter(
          (sale: Sale) =>
            sale.buyer === cleanAddress || sale.seller === cleanAddress
        );
        const uniqueTransactions = new Set(
          addressSales.map((sale: Sale) => sale.round)
        ).size;
        const mainnetPoints = uniqueTransactions * 2;
        const mTestnetPoints = testnetPoints[cleanAddress] || 0;

        const pxdBalance = new BigNumber(
          balancesData.balances.find(
            (token: TokenBalance) => token.symbol === "PXD"
          )?.balance || 0
        )
          .dividedBy(10 ** 8)
          .toNumber();

        const pxdPoints = pxdBalance * 3;
        const totalPoints = mTestnetPoints + mainnetPoints + pxdPoints;
        const estimatedAirdrop = (totalPoints / TOTAL_POINTS) * TOTAL_AIRDROP;

        setPoints({
          testnetPoints: mTestnetPoints,
          mainnetPoints,
          pxdPoints,
          totalPoints,
          estimatedAirdrop,
          isEligible: mainnetPoints > 0,
          uniqueTransactions,
          pxdBalance,
        });
      } catch (err) {
        setError(err instanceof Error ? err.message : "An error occurred");
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [address]);

  return { points, isLoading, error };
};
